{
  "name": "@aislop-inc/opencode-episodic-memory",
  "version": "0.4.3",
  "description": "Semantic search over past OpenCode conversations — local embeddings (Transformers.js), SQLite index, native plugin tools. Inspired by obra/episodic-memory, rebuilt natively for OpenCode.",
  "type": "module",
  "license": "MIT",
  "author": "robertn702",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/AISlop-Inc/opencode-episodic-memory.git"
  },
  "keywords": [
    "opencode",
    "plugin",
    "episodic-memory",
    "semantic-search",
    "embeddings",
    "transformersjs"
  ],
  "main": "./plugin/v2.ts",
  "exports": {
    ".": "./plugin/v2.ts",
    "./server": "./plugin/v2.ts",
    "./v2": "./plugin/v2.ts",
    "./cli": "./src/cli.ts"
  },
  "files": [
    "plugin",
    "src",
    "skills",
    "!src/*.test.ts",
    "!plugin/*.test.ts"
  ],
  "bin": {
    "opencode-episodic": "src/cli.ts"
  },
  "scripts": {
    "spike": "bun run spikes/spike.ts",
    "test": "bun test",
    "typecheck": "tsc --noEmit",
    "verify:entrypoint": "bun run spikes/verify-opencode-entrypoint.ts",
    "prepublishOnly": "bun run typecheck && bun test && bun run verify:entrypoint"
  },
  "dependencies": {
    "@libsql/client": "^0.18.0",
    "@huggingface/transformers": "^4.2.0",
    "@opencode/plugin": "^2.0.18",
    "zod": "^4.4.3"
  },
  "devDependencies": {
    "@types/bun": "latest",
    "typescript": "^7.0.2"
  },
  "trustedDependencies": [
    "onnxruntime-node",
    "protobufjs"
  ],
  "publishConfig": {
    "access": "public"
  }
}
